CREATE SEQUENCE IF NOT EXISTS "public"."roles_id_seq"
  AS integer
  START WITH 1
  INCREMENT BY 1
  MINVALUE 1
  MAXVALUE 2147483647
  CACHE 1
  NO CYCLE;

CREATE TABLE "public"."roles" (
  "id" serial NOT NULL,
  "name" character varying(20) NOT NULL,
  "description" character varying(255),
  "created_at" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT "roles_pkey" PRIMARY KEY (id),
  CONSTRAINT "roles_name_key" UNIQUE (name),
  CONSTRAINT "roles_name_check" CHECK (name::text = ANY (ARRAY['USER'::character varying, 'ADMIN'::character varying, 'EDITOR'::character varying, 'PRODUCTION'::character varying]::text[]))
);

INSERT INTO "public"."roles" ("id", "name", "description", "created_at") VALUES ('1', 'USER', 'Pengaju request buku', '2026-09-18 14:09:49.234836'), ('2', 'ADMIN', 'Administrator sistem dan approval', '2026-09-18 14:09:49.234836'), ('3', 'EDITOR', 'Pemeriksa materi buku', '2026-09-18 14:09:49.234836'), ('4', 'PRODUCTION', 'Pelaksana produksi buku', '2026-09-18 14:09:49.234836');

CREATE SEQUENCE IF NOT EXISTS "public"."users_id_seq"
  AS integer
  START WITH 1
  INCREMENT BY 1
  MINVALUE 1
  MAXVALUE 2147483647
  CACHE 1
  NO CYCLE;

CREATE TABLE "public"."users" (
  "id" serial NOT NULL,
  "username" character varying(50) NOT NULL,
  "email" character varying(120) NOT NULL,
  "password_hash" character varying(255) NOT NULL,
  "full_name" character varying(120) NOT NULL,
  "phone" character varying(30),
  "role_id" integer NOT NULL,
  "is_active" boolean NOT NULL DEFAULT true,
  "last_login_at" timestamp without time zone,
  "created_at" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updated_at" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT "users_pkey" PRIMARY KEY (id),
  CONSTRAINT "users_email_key" UNIQUE (email),
  CONSTRAINT "users_username_key" UNIQUE (username),
  CONSTRAINT "users_role_id_fkey" FOREIGN KEY ("role_id") REFERENCES "public"."roles"("id")
);
CREATE INDEX "idx_users_email" ON "public"."users" USING btree ("email");
CREATE INDEX "idx_users_is_active" ON "public"."users" USING btree ("is_active");
CREATE INDEX "idx_users_role" ON "public"."users" USING btree ("role_id");
CREATE INDEX "idx_users_username" ON "public"."users" USING btree ("username");

