CREATE SEQUENCE IF NOT EXISTS "public"."book_requests_id_seq"
  AS integer
  START WITH 1
  INCREMENT BY 1
  MINVALUE 1
  MAXVALUE 2147483647
  CACHE 1
  NO CYCLE;

CREATE TABLE "public"."book_requests" (
  "id" serial NOT NULL,
  "request_code" character varying(30) NOT NULL,
  "title" character varying(200) NOT NULL,
  "book_type_id" integer NOT NULL,
  "user_id" integer NOT NULL,
  "description" text,
  "member_count" integer NOT NULL DEFAULT 0,
  "deadline" date,
  "extra_note" text,
  "book_size" character varying(50),
  "paper_type" character varying(50),
  "print_quantity" integer,
  "finishing" character varying(50),
  "printing_note" text,
  "status" character varying(30) NOT NULL DEFAULT 'DRAFT'::character varying,
  "current_assignee_id" integer,
  "revision_count" integer NOT NULL DEFAULT 0,
  "submitted_at" timestamp without time zone,
  "completed_at" timestamp without time zone,
  "created_at" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updated_at" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "is_public" boolean NOT NULL DEFAULT false,
  CONSTRAINT "book_requests_pkey" PRIMARY KEY (id),
  CONSTRAINT "book_requests_request_code_key" UNIQUE (request_code),
  CONSTRAINT "book_requests_book_type_id_fkey" FOREIGN KEY ("book_type_id") REFERENCES "public"."book_types"("id"),
  CONSTRAINT "book_requests_current_assignee_id_fkey" FOREIGN KEY ("current_assignee_id") REFERENCES "public"."users"("id"),
  CONSTRAINT "book_requests_user_id_fkey" FOREIGN KEY ("user_id") REFERENCES "public"."users"("id"),
  CONSTRAINT "book_requests_member_count_check" CHECK (member_count >= 0),
  CONSTRAINT "book_requests_print_quantity_check" CHECK (print_quantity IS NULL OR print_quantity > 0),
  CONSTRAINT "book_requests_revision_count_check" CHECK (revision_count >= 0),
  CONSTRAINT "book_requests_status_check" CHECK (status::text = ANY (ARRAY['DRAFT'::character varying, 'SUBMITTED'::character varying, 'ADMIN_REVIEW'::character varying, 'ADMIN_APPROVED'::character varying, 'EDITOR_REVIEW'::character varying, 'REVISION_REQUIRED'::character varying, 'USER_REVISION'::character varying, 'EDITOR_APPROVED'::character varying, 'READY_FOR_PRODUCTION'::character varying, 'PRODUCTION'::character varying, 'QUALITY_CHECK'::character varying, 'COMPLETED'::character varying, 'REJECTED'::character varying, 'CANCELLED'::character varying]::text[]))
);
CREATE INDEX "idx_requests_assignee" ON "public"."book_requests" USING btree ("current_assignee_id");
CREATE INDEX "idx_requests_code" ON "public"."book_requests" USING btree ("request_code");
CREATE INDEX "idx_requests_created" ON "public"."book_requests" USING btree ("created_at");
CREATE INDEX "idx_requests_status" ON "public"."book_requests" USING btree ("status");
CREATE INDEX "idx_requests_type" ON "public"."book_requests" USING btree ("book_type_id");
CREATE INDEX "idx_requests_user" ON "public"."book_requests" USING btree ("user_id");

