CREATE SEQUENCE IF NOT EXISTS "public"."book_files_id_seq"
  AS integer
  START WITH 1
  INCREMENT BY 1
  MINVALUE 1
  MAXVALUE 2147483647
  CACHE 1
  NO CYCLE;

CREATE TABLE "public"."book_files" (
  "id" serial NOT NULL,
  "request_id" integer NOT NULL,
  "uploaded_by" integer NOT NULL,
  "category" character varying(30) NOT NULL DEFAULT 'SUPPORT'::character varying,
  "original_filename" character varying(255) NOT NULL,
  "stored_filename" character varying(255) NOT NULL,
  "mime_type" character varying(120) NOT NULL,
  "file_size" bigint NOT NULL,
  "file_path" character varying(500) NOT NULL,
  "revision_number" integer NOT NULL DEFAULT 0,
  "created_at" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT "book_files_pkey" PRIMARY KEY (id),
  CONSTRAINT "book_files_stored_filename_key" UNIQUE (stored_filename),
  CONSTRAINT "book_files_request_id_fkey" FOREIGN KEY ("request_id") REFERENCES "public"."book_requests"("id"),
  CONSTRAINT "book_files_uploaded_by_fkey" FOREIGN KEY ("uploaded_by") REFERENCES "public"."users"("id"),
  CONSTRAINT "book_files_category_check" CHECK (category::text = ANY (ARRAY['COVER'::character varying, 'MEMBER_PHOTO'::character varying, 'DOCUMENTATION'::character varying, 'SUPPORT'::character varying, 'ATTACHMENT'::character varying, 'FINAL'::character varying]::text[])),
  CONSTRAINT "book_files_file_size_check" CHECK (file_size > 0)
);
CREATE INDEX "idx_files_category" ON "public"."book_files" USING btree ("category");
CREATE INDEX "idx_files_request" ON "public"."book_files" USING btree ("request_id");

