CREATE SEQUENCE IF NOT EXISTS "public"."production_orders_id_seq"
  AS integer
  START WITH 1
  INCREMENT BY 1
  MINVALUE 1
  MAXVALUE 2147483647
  CACHE 1
  NO CYCLE;

CREATE TABLE "public"."production_orders" (
  "id" serial NOT NULL,
  "request_id" integer NOT NULL,
  "order_code" character varying(30) NOT NULL,
  "assigned_to" integer,
  "status" character varying(30) NOT NULL DEFAULT 'WAITING'::character varying,
  "note" text,
  "started_at" timestamp without time zone,
  "qc_at" timestamp without time zone,
  "completed_at" timestamp without time zone,
  "created_at" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updated_at" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT "production_orders_pkey" PRIMARY KEY (id),
  CONSTRAINT "production_orders_order_code_key" UNIQUE (order_code),
  CONSTRAINT "uq_production_request" UNIQUE (request_id),
  CONSTRAINT "production_orders_assigned_to_fkey" FOREIGN KEY ("assigned_to") REFERENCES "public"."users"("id"),
  CONSTRAINT "production_orders_request_id_fkey" FOREIGN KEY ("request_id") REFERENCES "public"."book_requests"("id"),
  CONSTRAINT "production_orders_status_check" CHECK (status::text = ANY (ARRAY['WAITING'::character varying, 'IN_PRODUCTION'::character varying, 'QUALITY_CHECK'::character varying, 'COMPLETED'::character varying]::text[]))
);
CREATE INDEX "idx_production_status" ON "public"."production_orders" USING btree ("status");

CREATE SEQUENCE IF NOT EXISTS "public"."request_revisions_id_seq"
  AS integer
  START WITH 1
  INCREMENT BY 1
  MINVALUE 1
  MAXVALUE 2147483647
  CACHE 1
  NO CYCLE;

CREATE TABLE "public"."request_revisions" (
  "id" serial NOT NULL,
  "request_id" integer NOT NULL,
  "revision_number" integer NOT NULL,
  "requested_by" integer,
  "editor_note" text NOT NULL,
  "user_response" text,
  "resolved_by" integer,
  "resolved_at" timestamp without time zone,
  "created_at" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT "request_revisions_pkey" PRIMARY KEY (id),
  CONSTRAINT "uq_revision_number" UNIQUE (request_id, revision_number),
  CONSTRAINT "request_revisions_request_id_fkey" FOREIGN KEY ("request_id") REFERENCES "public"."book_requests"("id"),
  CONSTRAINT "request_revisions_requested_by_fkey" FOREIGN KEY ("requested_by") REFERENCES "public"."users"("id"),
  CONSTRAINT "request_revisions_resolved_by_fkey" FOREIGN KEY ("resolved_by") REFERENCES "public"."users"("id"),
  CONSTRAINT "request_revisions_revision_number_check" CHECK (revision_number > 0)
);
CREATE INDEX "idx_revisions_request" ON "public"."request_revisions" USING btree ("request_id");

