CREATE SEQUENCE IF NOT EXISTS "public"."request_status_history_id_seq"
  AS integer
  START WITH 1
  INCREMENT BY 1
  MINVALUE 1
  MAXVALUE 2147483647
  CACHE 1
  NO CYCLE;

CREATE TABLE "public"."request_status_history" (
  "id" serial NOT NULL,
  "request_id" integer NOT NULL,
  "user_id" integer,
  "old_status" character varying(30),
  "new_status" character varying(30) NOT NULL,
  "note" text,
  "created_at" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT "request_status_history_pkey" PRIMARY KEY (id),
  CONSTRAINT "request_status_history_request_id_fkey" FOREIGN KEY ("request_id") REFERENCES "public"."book_requests"("id"),
  CONSTRAINT "request_status_history_user_id_fkey" FOREIGN KEY ("user_id") REFERENCES "public"."users"("id")
);
CREATE INDEX "idx_history_created" ON "public"."request_status_history" USING btree ("created_at");
CREATE INDEX "idx_history_request" ON "public"."request_status_history" USING btree ("request_id");

